/* ---- Tokens: the De Stijl palette ---- */
:root {
  --red: #E3170D;
  --blue: #20469B;
  --yellow: #F9D01E;
  --paper: #F6F3EA;
  --white: #FDFCF7;
  --grey: #C9C6BB;
  --ink: #101010;
  --body-ink: #33312B;
  --dim: #6B675C;
  --line: clamp(10px, 1.5vw, 15px);
  --font-sans: "Archivo", "Helvetica Neue", Arial, sans-serif;
  --font-mono: "Space Mono", "Courier New", monospace;
}

/* ---- Base ---- */
* { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; }
body {
  font-family: var(--font-sans);
  color: var(--body-ink);
  background: #E8E4D7;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}
::selection { background: var(--yellow); color: var(--ink); }
a:focus-visible { outline: 3px solid var(--blue); outline-offset: 3px; }
.skip-link {
  position: absolute; left: -999px; top: 0; z-index: 20;
  background: var(--ink); color: var(--white);
  padding: .8rem 1.2rem; font-family: var(--font-mono); font-size: .8rem;
}
.skip-link:focus { left: 0; }

/* ---- Page frame: one black-ruled composition ---- */
.frame {
  width: min(1240px, calc(100% - clamp(24px, 4vw, 48px)));
