  display: grid;
  gap: var(--line);
  background: var(--ink);
  border: var(--line) solid var(--ink);
}
main {
  display: grid;
  gap: var(--line);
  background: var(--ink);
}

/* ---- Top bar ---- */
.topbar {
  background: var(--paper);
  padding: .85rem clamp(1rem, 2vw, 1.5rem);
  display: flex; align-items: center; justify-content: space-between; gap: 1rem;
  font-family: var(--font-mono); font-weight: 700; font-size: .72rem;
  letter-spacing: .16em; text-transform: uppercase; color: var(--ink);
}
.palette { display: inline-flex; gap: 4px; }
.palette i { width: 13px; height: 13px; border: 2px solid var(--ink); display: block; }
.palette i:nth-child(1) { background: var(--red); }
.palette i:nth-child(2) { background: var(--blue); }
.palette i:nth-child(3) { background: var(--yellow); }

/* ---- Hero: the painting as a page grid ---- */
.hero { background: var(--ink); }
.hero-board {
  display: grid;
  gap: var(--line);
  background: var(--ink);
  grid-template-columns: minmax(0, 2.3fr) minmax(0, .7fr) minmax(0, 1.25fr);
  grid-template-rows: auto minmax(110px, .75fr) minmax(140px, 1fr);
  grid-template-areas:
    "txt txt red"
    "gry wht red"
    "blu wht yel";
}
.cell { background: var(--paper); }
.cell-txt { grid-area: txt; padding: clamp(1.75rem, 4vw, 4rem); }
.cell-red { grid-area: red; background: var(--red); }
.cell-gry { grid-area: gry; background: var(--grey); }
.cell-wht { grid-area: wht; background: var(--white); }
.cell-blu { grid-area: blu; background: var(--blue); }
.cell-yel { grid-area: yel; background: var(--yellow);
